    "code": "def insertion_sort(values):\n    values = values.copy()\n\n    for i in range(1, len(values)):\n        current = values[i]\n        j = i - 1\n\n        while j >= 0 and values[j] > current:\n            values[j + 1] = values[j]\n            j = j - 1\n\n        values[j + 1] = current\n\n    return values\n\n\nreadings = [4.2, 3.1, 5.0, 2.8, 3.7]\nprint(insertion_sort(readings))",
