    "id": "read-w-10-044",
    "bank": "wang",
    "reading": "wang",
    "chapter": 10,
    "chapterTitle": "Searching, Sorting and Program Efficiency",
    "topic": "algorithms",
    "name": "Complete worked example: ranking design alternatives",
    "source": "Wang · Ch. 10 · Example 44",
    "note": "Course reading example with fixed practice inputs. ",
    "code": "designs = [\n    {\"name\": \"A\", \"mass_kg\": 3.5, \"cost_USD\": 180, \"stress_MPa\": 140, \"yield_MPa\": 250},\n    {\"name\": \"B\", \"mass_kg\": 4.2, \"cost_USD\": 160, \"stress_MPa\": 100, \"yield_MPa\": 250},\n    {\"name\": \"C\", \"mass_kg\": 3.8, \"cost_USD\": 210, \"stress_MPa\": 90,  \"yield_MPa\": 250},\n    {\"name\": \"D\", \"mass_kg\": 3.9, \"cost_USD\": 190, \"stress_MPa\": 80,  \"yield_MPa\": 200},\n    {\"name\": \"E\", \"mass_kg\": 2.9, \"cost_USD\": 195, \"stress_MPa\": 110, \"yield_MPa\": 300},\n]\n\nrequired_fos = 2.0\nmax_mass = 4.0\nmax_cost = 200\n\nfeasible = []\n\nfor design in designs:\n    fos = design[\"yield_MPa\"] / design[\"stress_MPa\"]\n    design[\"fos\"] = fos\n\n    passes_strength = fos >= required_fos\n    passes_mass = design[\"mass_kg\"] <= max_mass\n    passes_cost = design[\"cost_USD\"] <= max_cost\n\n    if passes_strength and passes_mass and passes_cost:\n        feasible.append(design)\n\nif len(feasible) == 0:\n    print(\"No feasible design found.\")\nelse:\n    ranked = sorted(feasible, key=lambda d: (d[\"cost_USD\"], d[\"mass_kg\"]))\n    best = ranked[0]\n\n    print(\"FEASIBLE DESIGNS\")\n    print(\"----------------\")\n\n    for design in ranked:\n        print(\n            f\"{design['name']}: \"\n            f\"cost=${design['cost_USD']}, \"\n            f\"mass={design['mass_kg']:.1f} kg, \"\n            f\"FoS={design['fos']:.2f}\"\n        )\n\n    print()\n    print(f\"Recommended design: {best['name']}\")",
