    "code": "import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\ndef simulate_cooling(T_initial, T_ambient, k, dt, time_end):\n    if dt <= 0:\n        raise ValueError(\"dt must be positive\")\n    if k < 0:\n        raise ValueError(\"k must be nonnegative\")\n\n    times = np.arange(0.0, time_end + dt, dt)\n    temperatures = np.zeros(len(times))\n    temperatures[0] = T_initial\n\n    for i in range(1, len(times)):\n        T_old = temperatures[i - 1]\n        dTdt = -k * (T_old - T_ambient)\n        temperatures[i] = T_old + dTdt * dt\n\n    return times, temperatures\n\n\ndef first_time_below(times, values, limit):\n    for time, value in zip(times, values):\n        if value <= limit:\n            return time\n    return None\n\nT_initial = 100.0\nT_ambient = 25.0\nT_safe = 40.0\nrequired_time = 30.0\n\ndt = 0.25\ntime_end = 120.0\n\nrecords = []\n\nfor k in np.arange(0.02, 0.101, 0.005):\n    times, temperatures = simulate_cooling(\n        T_initial=T_initial,\n        T_ambient=T_ambient,\n        k=k,\n        dt=dt,\n        time_end=time_end\n    )\n\n    safe_time = first_time_below(times, temperatures, T_safe)\n\n    if safe_time is None:\n        meets_requirement = False\n    else:\n        meets_requirement = safe_time <= required_time\n\n    records.append({\n        \"k\": k,\n        \"safe_time_s\": safe_time,\n        \"final_temperature_degC\": temperatures[-1],\n        \"meets_requirement\": meets_requirement\n    })\n\n    plt.plot(times, temperatures, label=f\"k={k:.3f}\")\n\nresults = pd.DataFrame(records)\nacceptable = results[results[\"meets_requirement\"]]\n\nprint(results)\nprint(\"\\nAcceptable designs:\")\nprint(acceptable)\n\nif len(acceptable) > 0:\n    best = acceptable.sort_values(\"k\").iloc[0]\n    print(\"\\nSmallest acceptable cooling constant:\")\n    print(best)\nelse:\n    print(\"\\nNo acceptable design found.\")\n\nplt.axhline(T_safe, linestyle=\"--\", label=\"Safe temperature\")\nplt.axvline(required_time, linestyle=\"--\", label=\"Required time\")\nplt.xlabel(\"Time (s)\")\nplt.ylabel(\"Temperature (deg C)\")\nplt.title(\"Cooling Design Parameter Sweep\")\nplt.grid(True)\nplt.legend(fontsize=8)\nplt.show()",
